# Kept in sync with fixlist.file_hashes.HASH_LOG_TYPES.
HASH_LOG_TYPES = ['Malwarebytes', 'HitmanPro', 'MAU', 'Fixlog', 'Trojan Killer']


def backfill_file_hashes(apps, schema_editor):
    """Store the SHA256 rows of existing logs. Local parsing only (no
    centralbox call); a log that fails to parse is skipped, never fatal."""
    from fixlist.file_hashes import extract_file_hashes

    UploadedLog = apps.get_model('fixlist', 'UploadedLog')
    UploadedLogFileHash = apps.get_model('fixlist', 'UploadedLogFileHash')
    queryset = UploadedLog.objects.filter(log_type__in=HASH_LOG_TYPES).only('id', 'log_type', 'content')
    for upload in queryset.iterator(chunk_size=50):
        rows = extract_file_hashes(upload.log_type, upload.content or '')
        if not rows:
            continue
        UploadedLogFileHash.objects.bulk_create([
            UploadedLogFileHash(
                upload_id=upload.id, sha256=row.sha256, line_no=row.line_no,
                anchor_line_no=row.anchor_line_no, path=row.path,
                normalized_path=row.normalized_path, detection=row.detection,
                source=row.source, auto=row.auto,
            )
            for row in rows
        ], batch_size=1000)


